namespace {
inline uint32_t Product(const std::vector<int64_t>& dims, size_t start) {
    uint64_t v = 1;
    for (size_t i = start; i < dims.size(); ++i) v *= static_cast<uint64_t>(dims[i]);
    return static_cast<uint32_t>(v);
}
}

namespace optiling {
const uint32_t BLOCK_DIM = 8;

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    auto* inShape = context->GetInputShape(0);
    const auto& origin = inShape->GetOriginShape();
    std::vector<int64_t> dims;
    dims.assign(origin.GetDims(), origin.GetDims() + origin.GetDimNum());
    if (dims.size() < 4) return ge::GRAPH_FAILED;

    uint32_t n = static_cast<uint32_t>(dims[0]);
    uint32_t c = static_cast<uint32_t>(dims[1]);
    uint32_t spatial = Product(dims, 2);

    uint32_t tileNum = 8;
    if (spatial % tileNum != 0) {
        // 尽量选择能整除的tileNum
        for (uint32_t t = 16; t >= 1; --t) {
            if (spatial % t == 0) { tileNum = t; break; }
        }
    }

    uint32_t usedBlockDim = (n < BLOCK_DIM) ? n : BLOCK_DIM;
    if (usedBlockDim == 0) usedBlockDim = 1;
    context->SetBlockDim(usedBlockDim);

    Conv3dMultiplyInstanceNormClampMultiplyMaxCustomTilingData tiling;
    tiling.set_n(n);
    tiling.set_c(c);
    tiling.set_spatial(spatial);
    tiling.set_tileNum(tileNum);
    uint32_t nPerBlock = (n + usedBlockDim - 1) / usedBlockDim;
    tiling.set_nPerBlock(nPerBlock);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    const gert::Shape* x_shape = context->GetInputShape(0);
    if (x_shape->GetDimNum() < 4) return GRAPH_FAILED;
    std::vector<int64_t> in_dims(x_shape->GetDimNum());
    for (size_t i = 0; i < x_shape->GetDimNum(); ++i) in_dims[i] = x_shape->GetDim(i);
    // 输出形状 [N, D, H, W]，去掉通道维
    std::vector<int64_t> out_dims;
    out_dims.push_back(in_dims[0]);
    for (size_t i = 2; i < in_dims.size(); ++i) out_dims.push_back(in_dims[i]);
    gert::Shape* y_shape = context->GetOutputShape(0);
    y_shape->SetDimNum(out_dims.size());
    for (size_t i = 0; i < out_dims.size(); ++i) y_shape->SetDim(i, out_dims[i]);
    return GRAPH_SUCCESS;
}

